    donor_reputation: float,
    recipient_reputation: float,
    donor_action: str,
    recipient_action: str,
    my_reputation: float
) -> float:
    # Base step sizes: cooperate rewarded modestly, defect punished heavily
    step_coop = 0.2
    step_defect = -0.4

    # Determine if the action is considered "good" (Stern Judging core)
    good_recipient = recipient_reputation >= 0.0
    if donor_action == 'cooperate':
        good_action = good_recipient
    else:
        good_action = not good_recipient

    # Apply step with asymmetry
    if good_action:
        if donor_action == 'cooperate':
            step = step_coop
        else:
            step = -step_coop  # defect against bad recipient is good, reward with small positive?
    else:
        if donor_action == 'defect':
            step = step_defect
        else:
            step = -step_defect  # cooperate against bad recipient is bad, punish heavily

    # Incorporate my_reputation: if observer is very low reputation, be more lenient on bad actions
    if not good_action and my_reputation < -0.8:
        # Halve the punishment for bad actions when observer is disreputable
        step *= 0.5

    new_reputation = donor_reputation + step
    return max(-1.0, min(1.0, new_reputation))


